<?php
require_once __DIR__.'/../../includes/layout.php';require_login();check_csrf();$u=current_user();$teacher=campus_staff()||$u['role']==='Teacher';$student=$u['role']==='Student';if(!$teacher&&!$student){http_response_code(403);exit('Class attendance is available to students and assigned teaching staff.');}$error='';$sid=(int)($_GET['session']??$_POST['session']??0);
function attendance_window(int $id,bool $teacher): ?array {$sql='SELECT w.*,sc.subject_id,sc.section_id,sub.code AS subject_code,sub.title AS subject_title FROM attendance_windows w JOIN schedules sc ON sc.id=w.schedule_id JOIN subjects sub ON sub.id=sc.subject_id WHERE w.id=?';if($teacher&&!campus_staff())$sql.=' AND w.opened_by='.(int)current_user()['id'];if(!$teacher)$sql.=' AND sc.section_id IN(SELECT section_id FROM students WHERE user_id='.(int)current_user()['id'].')';return row($sql,[$id]);}
if($_SERVER['REQUEST_METHOD']==='POST')try {
    $action=(string)($_POST['action']??'');
    if($action==='open'&&$teacher){$schedule=row('SELECT * FROM schedules WHERE id=? '.(campus_staff()?'':'AND teacher_id='.teacher_id()),[(int)($_POST['schedule_id']??0)]);if(!$schedule)throw new InvalidArgumentException('Choose an assigned class schedule.');db()->prepare('INSERT INTO attendance_windows(schedule_id,opened_by,token,token_expires,expires_at) VALUES(?,?,?,?,?)')->execute([$schedule['id'],$u['id'],bin2hex(random_bytes(16)),time()+30,time()+900]);$sid=(int)db()->lastInsertId();log_activity($u['id'],'Attendance window opened','Window #'.$sid);redirect('rotating_attendance.php?session='.$sid);}
    $window=attendance_window($sid,$teacher);if(!$window){http_response_code(404);exit('Class window not found.');}
    if($teacher&&$action==='close'){db()->prepare('UPDATE attendance_windows SET closed=1 WHERE id=?')->execute([$sid]);set_flash('success','Attendance window closed.');redirect('rotating_attendance.php?session='.$sid);}
    if($teacher&&$action==='rotate'){
        if($window['closed']||$window['expires_at']<=time())throw new InvalidArgumentException('This attendance window has closed.');
        if($window['token_expires']<=time()){db()->prepare('UPDATE attendance_windows SET token=?,token_expires=? WHERE id=? AND token_expires<=?')->execute([bin2hex(random_bytes(16)),min(time()+30,(int)$window['expires_at']),$sid,time()]);$window=attendance_window($sid,true);}
        header('Content-Type: application/json');header('Cache-Control: no-store');echo json_encode(['session'=>$sid,'code'=>$window['token'],'expiresAt'=>(int)$window['token_expires']]);exit;
    }
    if($student&&$action==='checkin'){
        db()->beginTransaction();try{
            $window=attendance_window($sid,false);$code=(string)($_POST['code']??'');
            if(!$window||$window['closed']||$window['expires_at']<=time()||$window['token_expires']<=time()||!hash_equals($window['token'],$code))throw new InvalidArgumentException('This class code expired or is invalid. Scan the current QR shown by your teacher.');
            $s=row('SELECT * FROM students WHERE user_id=? AND section_id=?',[$u['id'],$window['section_id']]);if(!$s)throw new InvalidArgumentException('This class is not assigned to you.');
            $insert=db()->prepare('INSERT OR IGNORE INTO attendance_window_entries(window_id,student_id) VALUES(?,?)');$insert->execute([$sid,$s['id']]);
            $existing=scalar('SELECT COUNT(*) FROM attendance WHERE student_id=? AND subject_id=? AND date=?',[$s['id'],$window['subject_id'],date('Y-m-d')]);
            if($insert->rowCount()&&!$existing){db()->prepare('INSERT INTO attendance(student_id,subject_id,date,status,method,confidence,marked_by) VALUES(?,?,?,"Present","Rotating class QR",0,?)')->execute([$s['id'],$window['subject_id'],date('Y-m-d'),$window['opened_by']]);generate_prediction((int)$s['id'],false);}
            log_activity($u['id'],'Class QR check-in','Window #'.$sid);db()->commit();set_flash('success',$existing?'A class attendance record already exists. Ask your teacher for corrections.':'Your check-in was recorded. Your teacher can review the attendance status.');redirect('rotating_attendance.php?session='.$sid);
        }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw$e;}
    }
    throw new InvalidArgumentException('Choose a valid attendance action.');
}catch(InvalidArgumentException $e){if(($_POST['action']??'')==='rotate'){http_response_code(409);header('Content-Type: application/json');echo json_encode(['message'=>$e->getMessage()]);exit;}$error=$e->getMessage();}
$window=$sid?attendance_window($sid,$teacher):null;if($sid&&!$window){http_response_code(404);exit('Class window not found.');}render_header('Class QR attendance'); ?>
<div class="page-title"><div><span class="eyebrow">CLASS ATTENDANCE</span><h1>Rotating class QR</h1><p>Short-lived class codes and signed-in student check-ins. A rotating QR reduces stale sharing; it does not verify physical location.</p></div><?php if($teacher): ?><a class="btn btn-outline-primary" href="qr_attendance.php">Staff ID check-in</a><?php else: ?><a class="btn btn-outline-primary" href="../student/attendance.php">My attendance</a><?php endif; ?></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php if($teacher): ?><section class="panel"><h2>Open a class window</h2><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="action" value="open"><label>Assigned schedule<select name="schedule_id" class="form-select" required><?php foreach(rows('SELECT sc.*,sub.code,se.name AS section_name FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id JOIN sections se ON se.id=sc.section_id '.(campus_staff()?'':'WHERE sc.teacher_id='.teacher_id()).' ORDER BY sub.code') as $sc): ?><option value="<?= (int)$sc['id'] ?>"><?= e($sc['code'].' · '.$sc['section_name'].' · '.$sc['day_of_week'].' '.$sc['start_time']) ?></option><?php endforeach; ?></select></label><p>Windows last 15 minutes. Codes expire every 30 seconds. Open the window only when conducting the class, including approved make-up sessions.</p><button class="btn btn-primary">Open attendance window</button></form></section><?php endif; ?>
<?php if($window): ?><section class="panel"><h2><?= e($window['subject_code'].' · '.$window['subject_title']) ?></h2><?php if($window['closed']||$window['expires_at']<=time()): ?><p>This class window is closed.</p><?php elseif($teacher): ?><div data-class-window="<?= $sid ?>" data-class-csrf="<?= e(csrf_token()) ?>"><img class="campus-qr" alt="Current class attendance QR" data-class-qr hidden><p data-class-status role="status">Loading current class code…</p><p>Manual code: <code data-class-code></code></p></div><form method="post"><?= csrf_field() ?><input type="hidden" name="session" value="<?= $sid ?>"><button class="btn btn-outline-danger" name="action" value="close">Close attendance window</button></form><?php else: ?><p>Confirm your check-in for this class. Already recorded attendance will not be overwritten.</p><form method="post" class="campus-form" data-student-checkin><?= csrf_field() ?><input type="hidden" name="action" value="checkin"><input type="hidden" name="session" value="<?= $sid ?>"><label>Current class code<input name="code" maxlength="32" pattern="[a-f0-9]{32}" class="form-control" autocomplete="off" required data-student-code></label><button class="btn btn-primary">Confirm my check-in</button></form><?php endif; ?></section><?php else:if($student): ?><section class="panel"><h2>Scan your teacher's current QR</h2><p>Use your phone camera or scan the classroom QR to open the correct class window, then confirm your attendance while signed in.</p></section><?php endif;endif;render_footer(); ?>
